using sv_9d9a5de39624443197e481a62a33a63d.Models;

namespace sv_9d9a5de39624443197e481a62a33a63d.Services;

public class MockSettingsService : ISettingsService
{
    private UserProfile _profile = new(
        "Jane Doe",
        "jane.doe@example.com",
        "https://i.pravatar.cc/150?img=47",
        "Full-stack developer passionate about clean code and great UX.");

    private NotificationPrefs _notificationPrefs = new(
        EmailNotifications: true,
        PushNotifications: true,
        WeeklyDigest: false,
        MutedChannels: ["marketing", "random"]);

    private SecuritySettings _security = new(
        TwoFactorEnabled: true,
        LastPasswordChange: DateTime.UtcNow.AddDays(-45),
        Sessions:
        [
            new("sess-1", "Chrome on Windows", "New York, US", DateTime.UtcNow.AddMinutes(-5)),
            new("sess-2", "Safari on iPhone", "New York, US", DateTime.UtcNow.AddHours(-3)),
            new("sess-3", "Firefox on Linux", "London, UK", DateTime.UtcNow.AddDays(-2))
        ]);

    private AppearanceSettings _appearance = new("Light", "Medium", "English", false);

    private static readonly List<string> AllChannels =
        ["general", "engineering", "marketing", "random", "announcements", "support"];

    public Task<UserProfile> GetProfileAsync()
        => Simulate(() => _profile);

    public Task SaveProfileAsync(UserProfile profile)
        => Simulate(() => { _profile = profile; });

    public Task<NotificationPrefs> GetNotificationPrefsAsync()
    {
        // Ensure all known channels appear in MutedChannels tracking
        return Simulate(() => _notificationPrefs with
        {
            MutedChannels = [.._notificationPrefs.MutedChannels]
        });
    }

    public Task SaveNotificationPrefsAsync(NotificationPrefs prefs)
        => Simulate(() => { _notificationPrefs = prefs; });

    public Task<SecuritySettings> GetSecuritySettingsAsync()
        => Simulate(() => _security with { Sessions = [.. _security.Sessions] });

    public Task ChangePasswordAsync(string currentPassword, string newPassword)
    {
        return Simulate(() =>
        {
            if (currentPassword == "wrong")
                throw new InvalidOperationException("Current password is incorrect.");
            _security = _security with { LastPasswordChange = DateTime.UtcNow };
        });
    }

    public Task RevokeSessionAsync(string sessionId)
    {
        return Simulate(() =>
        {
            _security = _security with
            {
                Sessions = _security.Sessions.Where(s => s.Id != sessionId).ToList()
            };
        });
    }

    public Task<AppearanceSettings> GetAppearanceAsync()
        => Simulate(() => _appearance);

    public Task SaveAppearanceAsync(AppearanceSettings settings)
        => Simulate(() => { _appearance = settings; });

    // Expose all channels so the notifications section can render the full list
    public static IReadOnlyList<string> GetAllChannels() => AllChannels;

    private static async Task<T> Simulate<T>(Func<T> action)
    {
        await Task.Delay(150); // simulate latency
        return action();
    }

    private static async Task Simulate(Action action)
    {
        await Task.Delay(150);
        action();
    }
}

