{"file_text": "@using sv_9d9a5de39624443197e481a62a33a63d.Services
@using sv_9d9a5de39624443197e481a62a33a63d.Models
@inject ISettingsService SettingsService

<h4 class="mb-4">Appearance</h4>

@if (_loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border" role="status"><span class="visually-hidden">Loading...</span></div>
    </div>
}
else
{
    @if (!string.IsNullOrEmpty(_message))
    {
        <div class="alert @(_messageIsError ? "alert-danger" : "alert-success") alert-dismissible fade show" role="alert">
            @_message
            <button type="button" class="btn-close" @onclick="() => _message = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <!-- Theme -->
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title mb-3">Theme</h6>
                    @foreach (var theme in _themes)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                   value="@theme" checked="@(_theme == theme)"
                                   @onchange="() => _theme = theme" />
                            <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Font Size -->
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title mb-3">Font Size</h6>
                    @foreach (var size in _fontSizes)
                    {
                        <div class="form-check form-check-inline">
                            <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                                   value="@size" checked="@(_fontSize == size)"
                                   @onchange="() => _fontSize = size" />
                            <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                        </div>
                    }
                </div>
            </div>

            <!-- Language -->
            <div class="card mb-4">
                <div class="card-body">
                    <h6 class="card-title mb-3">Language</h6>
                    <select class="form-select" @bind="_language">
                        @foreach (var lang in _languages)
                        {
                            <option value="@lang">@lang</option>
                        }
                    </select>
                </div>
            </div>

            <!-- Compact Mode -->
            <div class="card mb-4">
                <div class="card-body d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-0">Compact Mode</h6>
                        <small class="text-muted">Reduce spacing and padding throughout the UI</small>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" @bind="_compactMode" style="transform: scale(1.3);" />
                    </div>
                </div>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="col-md-5">
            <div class="card position-sticky" style="top: 1rem;">
                <div class="card-header">
                    <i class="bi bi-eye me-1"></i> Live Preview
                </div>
                <div class="card-body @PreviewBgClass" style="@PreviewStyle transition: all 0.3s ease;">
                    <h6 class="@PreviewTextClass" style="@PreviewFontStyle">Sample Heading</h6>
                    <p class="@PreviewTextClass mb-2" style="@PreviewFontStyle">
                        This is how your content will look with the selected appearance settings.
                    </p>
                    <div class="d-flex gap-2 @(_compactMode ? "mb-1" : "mb-3")">
                        <span class="badge bg-primary">Tag</span>
                        <span class="badge bg-success">Active</span>
                        <span class="badge bg-warning text-dark">Pending</span>
                    </div>
                    <div class="@(_compactMode ? "p-1" : "p-2") border rounded @PreviewBorderClass" style="@PreviewFontStyle">
                        <small class="@PreviewTextClass">
                            <strong>Card element</strong> — @_language
                        </small>
                    </div>
                    <hr class="@PreviewBorderTopClass" />
                    <div class="d-flex justify-content-between align-items-center">
                        <small class="@PreviewMutedClass" style="@PreviewFontStyle">
                            Theme: @_theme &middot; Font: @_fontSize &middot; Compact: @(_compactMode ? "On" : "Off")
                        </small>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <button class="btn btn-primary mt-2" @onclick="SaveAsync" disabled="@_saving">
        @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
        Save
    </button>
}

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;

    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _messageIsError;

    private static readonly string[] _themes = ["Light", "Dark", "System"];
    private static readonly string[] _fontSizes = ["Small", "Medium", "Large"];
    private static readonly string[] _languages = ["English", "Spanish", "French", "German", "Japanese", "Chinese"];

    protected override async Task OnInitializedAsync()
    {
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            await SettingsService.SaveAppearanceAsync(new AppearanceSettings(_theme, _fontSize, _language, _compactMode));
            _message = "Appearance settings saved!";
            _messageIsError = false;
        }
        catch (Exception ex)
        {
            _message = $"Error: {ex.Message}";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    // Preview styling helpers
    private bool IsDark => _theme == "Dark";

    private string PreviewBgClass => IsDark ? "bg-dark" : "bg-light";
    private string PreviewTextClass => IsDark ? "text-light" : "text-dark";
    private string PreviewMutedClass => IsDark ? "text-secondary" : "text-muted";
    private string PreviewBorderClass => IsDark ? "border-secondary" : "";
    private string PreviewBorderTopClass => IsDark ? "border-secondary" : "";

    private string PreviewStyle => _fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private string PreviewFontStyle => _fontSize switch
    {
        "Small" => "font-size: 0.85em;",
        "Large" => "font-size: 1.15em;",
        _ => ""
    };
}
