@code {
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";

    // Saved state for discard
    private string _savedDisplayName = "";
    private string _savedEmail = "";
    private string _savedBio = "";
    private string _savedAvatarUrl = "";

    private bool _loading = true;
    private bool _saving;
    private string? _message;
    private bool _messageIsError;

    protected override async Task OnInitializedAsync()
    {
        var profile = await SettingsService.GetProfileAsync();
        ApplyProfile(profile);
        SaveSnapshot();
        _loading = false;
    }

    private void ApplyProfile(Models.UserProfile p)
    {
        _displayName = p.DisplayName;
        _email = p.Email;
        _bio = p.Bio;
        _avatarUrl = p.AvatarUrl;
    }

    private void SaveSnapshot()
    {
        _savedDisplayName = _displayName;
        _savedEmail = _email;
        _savedBio = _bio;
        _savedAvatarUrl = _avatarUrl;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _message = null;
        try
        {
            var profile = new Models.UserProfile(_displayName, _email, _avatarUrl, _bio);
            await SettingsService.SaveProfileAsync(profile);
            SaveSnapshot();
            _message = "Profile saved successfully!";
            _messageIsError = false;
        }
        catch (Exception ex)
        {
            _message = $"Error saving profile: {ex.Message}";
            _messageIsError = true;
        }
        finally
        {
            _saving = false;
        }
    }

    private void Discard()
    {
        _displayName = _savedDisplayName;
        _email = _savedEmail;
        _bio = _savedBio;
        _avatarUrl = _savedAvatarUrl;
        _message = null;
    }
}

