@page "/settings"
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <div class="settings-sidebar">
        <h5 class="px-3 py-2 mb-1 text-muted">Settings</h5>
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />
    </div>
    <div class="settings-content">
        @switch (_activeSection)
        {
            case "profile":
                <ProfileSection />
                break;
            case "notifications":
                <NotificationsSection />
                break;
            case "security":
                <SecuritySection />
                break;
            case "appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "profile";
}

.settings-container {
    display: flex;
    gap: 2rem;
    max-width: 1100px;
    margin: 0 auto;
}

.settings-sidebar {
    min-width: 200px;
    max-width: 220px;
    flex-shrink: 0;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

@media (max-width: 768px) {
    .settings-container {
        flex-direction: column;
        gap: 1rem;
    }

    .settings-sidebar {
        max-width: 100%;
    }
}

